INSERT INTO membrane_retrofits(assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES
('RT072-01','MR072-01','CN0327','west_shared_existing','conditional_screen',1,'高盐蒸发减量','除氟沉淀出水→耐盐NF/RO或ED试验→浓液原蒸发；低盐生化出水另论回用','conditional','氟盐结垢、AOX及污盐合规，原蒸发余量未核','高氟除氟蒸发已披露；实际电汽/处置费未知','仅对合适分股；不是已建设备','分股离子、AOX、渗透压、蒸发负荷与费用','除氟烧杯、离子/饱和指数、膜通量污染及浓液闭合','保持现有除氟蒸发；优先优化预处理',2,2,NULL,NULL,NULL,NULL,'氟盐/AOX和预处理为已知风险；其余无参数','2026-11-28'),
('RT072-02','MR072-02','CN0327','west_catalyst_and_polymer_expansion','conditional_screen',1,'新项目回用','确认扩建站后，从低盐洗水或出水开展UF/RO小试','unknown','混合项目不能以15900m³/a作为可回用量','批准扩建站及混合废水范围','实际运行与回用需求均未知','实际工艺、氟/盐/COD、流量、浓水去向、成本','分质采样、经济比较与浓水合规','现有站纳管；先分流优化',NULL,NULL,NULL,NULL,NULL,NULL,'缺扩建后工艺与实际水质','2026-11-28'),
('RT072-03','MR072-03','CN0328','east_shared_existing','conditional_screen',1,'东区回用或减排','低浓旁路优先单独评价UF/RO回用；高氟支路先除氟，不直接混合进膜','conditional','氟化钙结垢、浓水合规及生产水标准','600t/d生化及400t/d旁路为历史能力','公辅旁路并非可利用实际流量','实际旁路流量、TDS/Ca/F/Si、回用需求、电药费','分股采样、阻垢/通量及浓水平衡','现状纳管；优化二级沉淀',NULL,NULL,NULL,NULL,NULL,NULL,'无实测旁路盐度和经济参数','2026-11-28'),
('RT072-04','MR072-04','CN0156','production-design','conditional_screen',1,'小流量金属颗粒回收','优先保留分批沉淀过滤；仅有质量瓶颈时试验MF/UF抛光并保持原产品分流','not_recommended','SS高、金属交叉污染、处理量小；不改变回用配方','90及190.29m³/a设计，已分质回用；SS源强高','无实际损失或排放成本证明新增膜有经济性','实际水量、回用水质量问题、设备费用、滤渣去向','采样颗粒粒径、溶解金属及回用产品质量；比较过滤优化','维持PAC/PAM沉淀过滤，优化药剂和回用',2,1,NULL,NULL,NULL,NULL,'设计SS高，已有处理可优化；其他维度未知','2026-11-28'),
('RT072-05','MR072-05','CN0156','pre_upgrade_water','conditional_screen',1,'历史站优化','先核技改实际完成；如原线仍在运行，仅以小规模过滤优化为基准','unknown','历史水量非实际当前','原报告核算分股回用','不假设旧站仍运行','验收、真实流量与成本','确认生产线版本后做分批采样','保留现有回用',NULL,NULL,NULL,NULL,NULL,NULL,'尚无实际当前数据','2026-11-28');
INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N072-01','CN0327','S072-01','厂界与历史工艺','3.4.1、4.1','西区原浙江化工院科技有限公司；报告300t/d生化，批准297.98t/d生化及64.46t/d旁路（合362.44t/d）；报告约260t/d实际处理。高氟pH8–9除氟+蒸发；生化前pH6–8。干泥外运，滤液回流。历史站不等同扩建后运行。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N072-02','CN0327','S072-02','批准项目边界','批复pp1–2截图','400t/a催化剂+200t/a含氟聚合物后处理，共享500t/d站；15900m³/a项目混合排水上限，西区124633m³/a。水膜除尘是废气设备而非污水膜。','WEB_PRIMARY','WEB_TEXT+SCREEN','2026-11-28'),
('N072-03','CN0328','S072-01','独立厂区与历史运行','3.8.1–3.8.4','2019吸收合并后东、西区分别申报许可且不合并排放；东区2022改造600t/d生化+400t/d低浓旁路，2023监测属于全厂。AOX原表ug/L与标准5.0疑义；不自动换算标准。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N072-04','CN0328','S072-03','历史制造范围','安全现状评价简介','东区纬七路5号，披露100t/a氟化铝催化剂；西区纬五路31号。不得认定2026实际产量或将东区旧产能与西区新批规模直接相加。','WEB_SECONDARY','WEB_TEXT','2026-11-28'),
('N072-05','CN0156','turn699489search96','分批回用与设施口径','2.4.6.2、3.7.2、3.9.2-1/3及图3.9.2-1','现有1m³/d站依托；喷淋按五产品分别收集处理回用，拖洗单独；设计年运行300d、约281m³/a处理需求（报告取整），合计280.29m³/a产生量。无反应废水不等于无工业辅助废水；设计水质非实测。原报告设备表不公开，截图超时。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N072-06','CN0156','turn699489search96','技改变更及厂址','概述、3.2.1','临淄敬仲镇工业集聚区；总2500t/a不变，9产品减5，3旧窑替换、18设备拆除及38设备新增，增加水喷淋。未取得验收。','WEB_PRIMARY','WEB_TEXT','2026-11-28');
